import struct
import json

data = open('/app/trunc.db', 'rb').read()

def read_varint(buf, offset):
    result = 0
    for i in range(9):
        if offset + i >= len(buf):
            return None, offset
        byte = buf[offset + i]
        if i == 8:
            result = (result << 8) | byte
            return result, offset + 9
        result = (result << 7) | (byte & 0x7f)
        if (byte & 0x80) == 0:
            return result, offset + i + 1
    return result, offset + 9

def read_int(buf, offset, size):
    """Read a big-endian signed integer of given size (1-8 bytes)"""
    val = int.from_bytes(buf[offset:offset+size], 'big', signed=True)
    return val, size

def read_serial_data(buf, offset, serial_type):
    if serial_type == 0:
        return None, 0
    elif 1 <= serial_type <= 6:
        return read_int(buf, offset, serial_type)
    elif serial_type == 7:
        return struct.unpack('>d', buf[offset:offset+8])[0], 8
    elif serial_type == 8:
        return 0, 0
    elif serial_type == 9:
        return 1, 0
    elif serial_type >= 13:
        size = (serial_type - 13) // 2
        return buf[offset:offset+size], size
    else:
        return None, 0

def parse_record(buf, offset):
    header_size, pos = read_varint(buf, offset)
    if header_size is None or header_size < 2:
        return None
    col_types = []
    type_end = offset + header_size
    while pos < type_end:
        st, pos = read_varint(buf, pos)
        if st is None:
            return None
        col_types.append(st)
    col_data = []
    for st in col_types:
        val, size = read_serial_data(buf, pos, st)
        col_data.append(val)
        pos += size
    return col_data

results = []
idx = 0
while True:
    idx = data.find(b'testword', idx)
    if idx == -1:
        break
    record_start = idx - 4
    cell_start = record_start - 2
    if cell_start >= 0:
        payload_len, after_payload = read_varint(data, cell_start)
        rowid, after_rowid = read_varint(data, after_payload)
        if after_rowid == record_start:
            record = parse_record(data, record_start)
            if record and len(record) == 3:
                word = record[1].decode('utf-8') if isinstance(record[1], bytes) else record[1]
                value = record[2]
                results.append({"word": word, "value": value})
    idx += 1

results.sort(key=lambda x: x["word"])

for r in results:
    print(r)

with open('/app/recover.json', 'w') as f:
    json.dump(results, f)
